        Vec2(nil, x + w, y + h),
        Vec2(nil, x, y + h)
    }
end
function HUD.prototype.screenVerts(self, w, h)
    return self:rectVerts(-w / 2, -h / 2, w, h)
end
function HUD.prototype.circle(self, draw, cx, cy, r, segs, width, color, from, sweep)
    do
        local i = 0
        while i < segs do
            local a0 = from + i / segs * sweep
            local a1 = from + (i + 1) / segs * sweep
            draw:drawSegment(
                Vec2(
                    nil,
                    cx + math.cos(a0) * r,
                    cy + math.sin(a0) * r
                ),
                Vec2(
                    nil,
                    cx + math.cos(a1) * r,
                    cy + math.sin(a1) * r
                ),
                width,
                col(nil, color)
            )
            i = i + 1
        end
    end
end
