        end
    end
    if self.barFrameSp ~= nil then
        self.barFrameSp.visible = true
        self.barFrameSp.position = Vec2(nil, barX, bottomY)
    end
    if self.barFillSp ~= nil then
        local rw = math.floor(16 * ratio + 0.5)
        self.barFillSp.visible = rw > 0
        if rw > 0 then
            self.barFillSp.textureRect = Rect(
                nil,
                0,
                0,
                rw,
                10
            )
            self.barFillSp.position = Vec2(nil, barX + FILL_PAD_X, bottomY + FILL_PAD_Y)
        end
    end
    return true
end
function HUD.prototype.drawTitleBg(self, w, h)
    self.titleBg:clear()
    self.titleBg:drawPolygon(
        self:screenVerts(w, h),
        Palette.paper
    )
    local mx = w / 2 - 190
    local my = h / 2 - 170
    self:circle(
        self.titleBg,
        mx,
        my,
        96,
        40,
        2,
        Palette.goldSoft,
        0,
        math.pi * 2
    )
    self.titleBg:drawDot(
        Vec2(nil, mx, my),
        84,
        col(nil, Palette.moonWhite)
    )
    do
        local i = 0
        while i < 4 do
            local x0 = -w / 2 + i * (w / 3.2)
            self.titleBg:drawSegment(
                Vec2(nil, x0, -h / 2 + 40 + i * 14),
                Vec2(nil, x0 + w / 3.6, -h / 2 + 26 + i * 14),
                26 + i * 8,
                col(nil, Palette.paleInkFar)
            )
            i = i + 1
        end
    end
end
function HUD.prototype.drawPauseBg(self, w, h)
    self.pauseBg:clear()
    self.pauseBg:drawPolygon(
        self:screenVerts(w, h),
        col(nil, Palette.inkWash)
    )
    self.pauseBg:drawPolygon(
        self:rectVerts(-320, -220, 640, 440),
        col(nil, Palette.paper),
        2,
        col(nil, Palette.inkDark)
    )
    self.pauseBg:drawPolygon(
        self:rectVerts(-308, -208, 616, 416),
        col(nil, NO_FILL),
        1,
        col(nil, Palette.goldSoft)
    )
end
function HUD.prototype.flashDamage(self)
    self.flashTimer = FLASH_TIME
end
function HUD.prototype.setRewind(self, v)
    self.rewindV = v
    if self.rewindLb ~= nil then
        self.rewindLb.visible = v >= 0
    end
end
function HUD.prototype.showEnding(self, id)
    local e = ENDINGS[id]
    if e == nil then
        return
    end
    local w = View.size.width
    local h = View.size.height
    self.endingBg:clear()
    self.endingBg:drawPolygon(
        self:screenVerts(w, h),
        col(
            nil,
            ink(
                nil,
                Palette.paper.r,
                Palette.paper.g,
                Palette.paper.b,
                242
            )
        )
    )
    self.endingBg:drawPolygon(
        self:rectVerts(-w / 2 + 14, -h / 2 + 14, w - 28, h - 28),
        col(nil, NO_FILL),
        1,
        col(nil, Palette.goldSoft)
    )
    setText(nil, self.endingTitleLb, e.title)
    do
        local i = 0
        while i < #self.endingLineLbs do
            setText(nil, self.endingLineLbs[i + 1], i < #e.lines and e.lines[i + 1] or "")
            i = i + 1
        end
    end
    self.endingNode.visible = true
end
function HUD.prototype.hideEnding(self)
    self.endingNode.visible = false
end
function HUD.prototype.setTitleVisible(self, v)
    self.titleNode.visible = v
end
function HUD.prototype.setPauseVisible(self, v)
    self.pauseNode.visible = v
end
function HUD.prototype.update(self, dt, args)
    local st = args.state
    local w = View.size.width
    local h = View.size.height
    local top = h / 2
    self.hud:clear()
    local baseX = -w / 2 + 44
    local rowY = top - 44
    local pxLife = self:updatePixelLife(st, baseX - 4, rowY)
    if not pxLife then
        do
            local i = 0
            while i < st.maxLife do
                local x = baseX + i * 30
                if i < st.heroineLife then
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        Palette.vermilion,
                        2,
                        Palette.inkDark
                    )
                else
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        NO_FILL,
                        2,
                        Palette.inkFaint
                    )
                end
                i = i + 1
            end
        end
    end
    local ix0 = pxLife and baseX - 4 + 3 * HEART_STEP + 16 + 64 * BAR_SCALE + 16 or baseX + st.maxLife * 30 + 26
    do
        local i = 0
        while i < st.maxSwordIntent do
            local x = ix0 + i * 16
            if i < st.swordIntent then
                self.hud:drawSegment(
                    Vec2(nil, x, rowY - 10),
                    Vec2(nil, x, rowY + 10),
                    4,
                    col(nil, Palette.moonCyan)
                )
            else
                self.hud:drawSegment(
                    Vec2(nil, x, rowY - 10),
                    Vec2(nil, x, rowY + 10),
                    2,
                    col(nil, Palette.inkFaint)
                )
            end
            i = i + 1
        end
    end
    local cx = w / 2 - 74
    local cy = top - 40
    self:circle(
        self.hud,
        cx,
        cy,
        22,
        28,
        2,
        Palette.gold,
        0,
        math.pi * 2
    )
    local phase = st.phaseIndex
    local illum = (1 - math.cos(phase / 8 * math.pi * 2)) / 2
    if phase == 0 then
        self.hud:drawDot(
            Vec2(nil, cx, cy),
            9,
            col(nil, Palette.inkWash)
        )
    else
        self.hud:drawDot(
            Vec2(nil, cx, cy),
            5 + 12 * illum,
            col(nil, Palette.moonWhite)
        )
        self.hud:drawDot(
            Vec2(nil, cx + (phase < 4 and 12 or -12), cy),
            3,
            col(nil, Palette.goldSoft)
        )
    end
    setText(nil, self.phaseLb, phase >= 0 and phase < #PHASE_NAMES and PHASE_NAMES[phase + 1] or "")
    setText(
        nil,
        self.loopLb,
        ("第" .. tostring(st.loopIndex + 1)) .. "周目"
    )
    local trust = st.shenyanTrust
    setText(
        nil,
        self.trustLb,
        ("砚·信任 " .. tostring(trust)) .. " / 4"
    )
    if self.trustLb ~= nil then
        self.trustLb.color = trust >= 4 and Color(
            nil,
            Palette.moonCyan.r,
            Palette.moonCyan.g,
            Palette.moonCyan.b,
            255
        ) or Color(
            nil,
            Palette.paleInk.r,
            Palette.paleInk.g,
            Palette.paleInk.b,
            255
        )
    end
    setText(nil, self.objectiveLb, args.objective)
    setText(nil, self.hintLb, args.hint)
    local boss = args.boss
    if boss ~= nil and not boss.dead and boss.maxHp > 0 then
        local bw = 520
        local bx = -bw / 2
        local by = -h / 2 + 66
        self.hud:drawPolygon(
            self:rectVerts(bx, by, bw, 12),
            col(nil, NO_FILL),
            2,
            col(nil, Palette.inkDark)
        )
        local frac = math.max(
            0,
            math.min(1, boss.hp / boss.maxHp)
        )
        if frac > 0 then
            self.hud:drawPolygon(
                self:rectVerts(bx + 2, by + 2, (bw - 4) * frac, 8),
                col(nil, Palette.vermilion)
            )
        end
    end
    self.flash:clear()
    if self.flashTimer > 0 then
        self.flashTimer = math.max(0, self.flashTimer - dt)
        local a = math.floor(255 * 0.35 * (self.flashTimer / FLASH_TIME))
        self.flash:drawPolygon(
            self:screenVerts(w, h),
            col(
                nil,
                ink(
                    nil,
                    Palette.vermilion.r,
                    Palette.vermilion.g,
                    Palette.vermilion.b,
                    a
                )
            )
        )
    end
    self.rewindDraw:clear()
    if self.rewindV >= 0 then
        local v = math.max(
            0,
            math.min(1, self.rewindV)
        )
        self.rewindDraw:drawPolygon(
            self:screenVerts(w, h),
            col(nil, Palette.mist)
        )
        self:circle(
            self.rewindDraw,
            0,
            0,
            46,
            36,
            4,
            Palette.moonCyan,
            -math.pi / 2,
            v * math.pi * 2
        )
    end
    if self.titleNode.visible and self.titleStartLb ~= nil then
        local a = 150 + math.floor(100 * math.sin(args.time * 2.6))
        self.titleStartLb.color = Color(
            nil,
            Palette.inkSoft.r,
            Palette.inkSoft.g,
            Palette.inkSoft.b,
            a
        )
    end
end
return ____exports
